// Meertaligheid voor de chauffeurschermen.
//
// Chauffeurs komen uit veel landen; de meldingflow is voor hen vertaald.
// Nederlands is de standaard (de rest van de app — beheer/werkplaats — blijft
// Nederlands, dat zijn de bedrijfsmedewerkers). De taalkeuze wordt onthouden
// in localStorage en via een event verspreid zodat alle schermen mee-updaten.

// NB: Armeens (hy) is op verzoek uit de keuzelijst gehaald; de vertalingen
// staan nog in DICT, dus terugzetten is één regel.
export const LANGS = [
  { code: "nl", label: "Nederlands", flag: "🇳🇱" },
  { code: "en", label: "English", flag: "🇬🇧" },
  { code: "pl", label: "Polski", flag: "🇵🇱" },
  { code: "ro", label: "Română", flag: "🇷🇴" },
  { code: "bg", label: "Български", flag: "🇧🇬" },
  { code: "uk", label: "Українська", flag: "🇺🇦" },
  { code: "ru", label: "Русский", flag: "🇷🇺" },
  { code: "tr", label: "Türkçe", flag: "🇹🇷" },
  { code: "ka", label: "ქართული", flag: "🇬🇪" },
  { code: "lt", label: "Lietuvių", flag: "🇱🇹" },
];

const KEY = "tt_lang";

export function getLang() {
  try {
    const l = localStorage.getItem(KEY);
    if (l && LANGS.some((x) => x.code === l)) return l;
  } catch { /* geen localStorage */ }
  return "nl";
}

export function setLang(code) {
  try { localStorage.setItem(KEY, code); } catch { /* noop */ }
  if (typeof window !== "undefined") window.dispatchEvent(new CustomEvent("tt-lang", { detail: code }));
}

// Vertaling ophalen. Valt terug op Nederlands, dan op de sleutel zelf.
export function t(key, lang = getLang()) {
  const d = DICT[lang] || DICT.nl;
  if (d && d[key] != null) return d[key];
  if (DICT.nl[key] != null) return DICT.nl[key];
  return key;
}

